SELECT 'Electronics', 'electronics', NULL, 1, 'Headphones, laptops, mobiles, wearables and more', '/images/store/tiles/tile-electronics.png'
WHERE NOT EXISTS (SELECT 1 FROM categories WHERE slug = 'electronics');

